#include "diff.hpp"
#include <algorithm>
#include <vector>

namespace {
	std::vector<std::string> lines_of(std::string const& text)
	{
		std::vector<std::string> lines;
		size_t                   start = 0;
		for (size_t at = 0; at < text.size(); at++) {
			if ((text[at] == '\n') || ((text[at] == '\r') && !((at + 1 < text.size()) && (text[at + 1] == '\n')))) {
				lines.push_back(text.substr(start, at + 1 - start));
				start = at + 1;
			}
		}
		if (start < text.size()) {
			lines.push_back(text.substr(start));
		}
		return lines;
	}

	std::string body(std::string line)
	{
		while (!line.empty() && ((line.back() == '\n') || (line.back() == '\r'))) {
			line.pop_back();
		}
		return line;
	}

	struct edit {
		char   op; // ' ' kept, '-' removed, '+' added
		size_t line;
	};

	// Myers' O(ND) difference. The kept lines at both ends are cut off first, which is most of a file.
	std::vector<edit> diff_lines(std::vector<std::string> const& a, std::vector<std::string> const& b)
	{
		size_t head = 0;
		while ((head < a.size()) && (head < b.size()) && (a[head] == b[head])) {
			head++;
		}
		size_t tail = 0;
		while ((tail < a.size() - head) && (tail < b.size() - head) && (a[a.size() - 1 - tail] == b[b.size() - 1 - tail])) {
			tail++;
		}

		std::vector<edit> out;
		for (size_t i = 0; i < head; i++) {
			out.push_back({ ' ', i });
		}

		int n = int(a.size() - head - tail);
		int m = int(b.size() - head - tail);
		auto A = [&](int i) -> std::string const& { return a[head + size_t(i)]; };
		auto B = [&](int i) -> std::string const& { return b[head + size_t(i)]; };

		std::vector<edit> middle;
		if ((n == 0) || (m == 0)) {
			for (int i = 0; i < n; i++) {
				middle.push_back({ '-', head + size_t(i) });
			}
			for (int j = 0; j < m; j++) {
				middle.push_back({ '+', head + size_t(j) });
			}
		} else {
			int                           max = n + m;
			std::vector<int>              v(size_t(2 * max + 2), 0);
			std::vector<std::vector<int>> trace;
			auto                          idx = [&](int k) { return size_t(k + max); };
			int                           found = -1;
			for (int d = 0; d <= max && found < 0; d++) {
				trace.push_back(v);
				for (int k = -d; k <= d; k += 2) {
					int x;
					if ((k == -d) || ((k != d) && (v[idx(k - 1)] < v[idx(k + 1)]))) {
						x = v[idx(k + 1)];
					} else {
						x = v[idx(k - 1)] + 1;
					}
					int y = x - k;
					while ((x < n) && (y < m) && (A(x) == B(y))) {
						x++;
						y++;
					}
					v[idx(k)] = x;
					if ((x >= n) && (y >= m)) {
						found = d;
						break;
					}
				}
			}
			// Walk back through the trace.
			int x = n, y = m;
			for (int d = found; d > 0; d--) {
				auto const& pv = trace[size_t(d)];
				int         k  = x - y;
				int         pk = ((k == -d) || ((k != d) && (pv[idx(k - 1)] < pv[idx(k + 1)]))) ? k + 1 : k - 1;
				int         px = pv[idx(pk)];
				int         py = px - pk;
				while ((x > px) && (y > py)) {
					x--;
					y--;
					middle.push_back({ ' ', head + size_t(x) });
				}
				if (x == px) {
					y--;
					middle.push_back({ '+', head + size_t(y) });
				} else {
					x--;
					middle.push_back({ '-', head + size_t(x) });
				}
			}
			while ((x > 0) && (y > 0)) {
				x--;
				y--;
				middle.push_back({ ' ', head + size_t(x) });
			}
			std::reverse(middle.begin(), middle.end());
		}
		out.insert(out.end(), middle.begin(), middle.end());
		for (size_t i = 0; i < tail; i++) {
			out.push_back({ ' ', a.size() - tail + i });
		}
		return out;
	}
} // namespace

std::string blitz::tools::unified_diff(std::string const& old_text, std::string const& new_text, std::string const& old_name, std::string const& new_name)
{
	if (old_text == new_text) {
		return {};
	}
	auto a = lines_of(old_text);
	auto b = lines_of(new_text);

	// Give every edit both line numbers: for kept lines the old one maps to the new one by counting.
	auto edits = diff_lines(a, b);
	struct entry {
		char        op;
		size_t      old_no, new_no; // 0 based position of the next line
		std::string text;
	};
	std::vector<entry> entries;
	size_t             oi = 0, ni = 0;
	for (auto const& e : edits) {
		std::string text = (e.op == '+') ? body(b[e.line]) : body(a[e.line]);
		entries.push_back({ e.op, oi, ni, text });
		if (e.op != '+') {
			oi++;
		}
		if (e.op != '-') {
			ni++;
		}
	}

	constexpr size_t context = 3;
	std::string      out     = "--- " + old_name + "\n+++ " + new_name + "\n";
	size_t           i       = 0;
	while (i < entries.size()) {
		while ((i < entries.size()) && (entries[i].op == ' ')) {
			i++;
		}
		if (i >= entries.size()) {
			break;
		}
		size_t begin = (i > context) ? i - context : 0;
		// Extend the hunk until three kept lines in a row.
		size_t end  = i;
		size_t kept = 0;
		for (size_t j = i; j < entries.size(); j++) {
			if (entries[j].op == ' ') {
				kept++;
				if (kept > 2 * context) {
					break;
				}
			} else {
				kept = 0;
				end  = j;
			}
		}
		size_t stop = std::min(entries.size(), end + 1 + context);

		size_t old_count = 0, new_count = 0;
		for (size_t j = begin; j < stop; j++) {
			old_count += (entries[j].op != '+');
			new_count += (entries[j].op != '-');
		}
		size_t old_start = entries[begin].old_no + (old_count ? 1 : 0);
		size_t new_start = entries[begin].new_no + (new_count ? 1 : 0);
		out += "@@ -" + std::to_string(old_start) + "," + std::to_string(old_count) + " +" + std::to_string(new_start) + "," + std::to_string(new_count) + " @@\n";
		for (size_t j = begin; j < stop; j++) {
			out += entries[j].op;
			out += entries[j].text;
			out += "\n";
		}
		i = stop;
	}
	return out;
}
